// Review-only; intentionally no FighterView, support catalog or shipping prefab mutation.
public static class IslandNativeStrikeReviewJob {
 const string Folder="Assets/IslandNativeStrikeReview";
 const string SHA="5cc8b7208f3267cb1e20909bcff4eb04a9b9bf58ce7f28ebb77bbdb516c41a24";
 static readonly string[] Names={"box_01","box_02","front_kick_01"};
 static readonly float[] Durations={53f/24,67f/24,60f/24};
 static readonly string[] Fields={"px","py","pz","qx","qy","qz","qw","sx","sy","sz"};
 static string Arg(string key,string fallback=null){var a=Environment.GetCommandLineArgs();int n=Array.IndexOf(a,key);return n>=0&&n+1<a.Length?a[n+1]:fallback;}
 static string Hash(byte[] bytes){using(var s=SHA256.Create())return BitConverter.ToString(s.ComputeHash(bytes)).Replace("-","").ToLowerInvariant();}
 static void OwnedProject(){string root=Path.GetFullPath(Path.GetDirectoryName(Application.dataPath));if(!root.Replace('\\','/').Contains("/.tools/tripo-humanoid-review-unity/"))throw new Exception("Island job is restricted to its owned isolated QA project, never main");Directory.SetCurrentDirectory(root);}
 [Serializable]sealed class ImportPolicy{public string templatePath,templateMetaSHA,sourceSHA,normals,tangents,normalCalculationMode,normalSmoothingSource;public bool resampleCurves,templateResampleCurves,optimizeBones;public int meshOptimizationFlags;public float normalSmoothingAngle;}
 [Serializable]sealed class TakeHash{public string take,sha256;}
 [Serializable]sealed class RawCompletion{public string status,sourceSHA,rawMetaSHA,meshSHA,renderSHA,importPolicySHA;public TakeHash[] files;}
 [Serializable]sealed class Authority{public bool passed=false;public string sourceSHA256="";public int fitCount=0,holdoutPhases=0;public TakeHash[] unityCSVFiles=new TakeHash[0];}
 public static void Prepare(){MeasureOriginal();}
 public static void MeasureOriginal(){
  OwnedProject();
  string input=Arg("-islandNativeSource");if(string.IsNullOrEmpty(input)||Hash(File.ReadAllBytes(input))!=SHA)throw new Exception("Exact Island native FBX SHA gate failed");
  string path=Folder+"/Source/model.fbx";Directory.CreateDirectory(Folder+"/Source");Directory.CreateDirectory(Folder+"/Poses");Directory.CreateDirectory("IslandStrikeEvidence");
  if(File.Exists(path)&&Hash(File.ReadAllBytes(path))!=SHA)throw new Exception("Review input already exists with different bytes");
  if(!File.Exists(path))File.Copy(input,path);AssetDatabase.Refresh();
  string templatePath=Arg("-islandImportTemplate","Assets/LighFight/Art/Drafts/TripoIslandPlayable/Source/Island/model.fbx");var template=AssetImporter.GetAtPath(templatePath) as ModelImporter;if(template==null||templatePath==path||Hash(File.ReadAllBytes(templatePath))!=SHA)throw new Exception("Supply separate owned calibrated Island source-identical import template");string templateMetaSHA=Hash(File.ReadAllBytes(templatePath+".meta"));
  var importer=(ModelImporter)AssetImporter.GetAtPath(path);importer.animationType=ModelImporterAnimationType.Generic;importer.avatarSetup=ModelImporterAvatarSetup.CreateFromThisModel;importer.animationCompression=ModelImporterAnimationCompression.Off;importer.meshCompression=ModelImporterMeshCompression.Off;importer.isReadable=true;importer.optimizeGameObjects=false;importer.weldVertices=false;importer.skinWeights=ModelImporterSkinWeights.Custom;importer.maxBonesPerVertex=8;importer.minBoneWeight=0;importer.resampleCurves=false;importer.importNormals=template.importNormals;importer.importTangents=template.importTangents;importer.meshOptimizationFlags=template.meshOptimizationFlags;importer.optimizeBones=template.optimizeBones;importer.normalCalculationMode=template.normalCalculationMode;importer.normalSmoothingSource=template.normalSmoothingSource;importer.normalSmoothingAngle=template.normalSmoothingAngle;importer.importBlendShapeNormals=template.importBlendShapeNormals;importer.SaveAndReimport();
  if(importer.resampleCurves||importer.importNormals!=template.importNormals||importer.importTangents!=template.importTangents||importer.meshOptimizationFlags!=template.meshOptimizationFlags)throw new Exception("Explicit raw import policy was not retained");File.WriteAllText("IslandStrikeEvidence/import-policy.json",JsonUtility.ToJson(new ImportPolicy{templatePath=templatePath,templateMetaSHA=templateMetaSHA,sourceSHA=SHA,resampleCurves=importer.resampleCurves,templateResampleCurves=template.resampleCurves,normals=importer.importNormals.ToString(),tangents=importer.importTangents.ToString(),meshOptimizationFlags=(int)importer.meshOptimizationFlags,optimizeBones=importer.optimizeBones,normalCalculationMode=importer.normalCalculationMode.ToString(),normalSmoothingSource=importer.normalSmoothingSource.ToString(),normalSmoothingAngle=importer.normalSmoothingAngle},true));
  var model=AssetDatabase.LoadAssetAtPath<GameObject>(path);var mesh=model.GetComponentInChildren<SkinnedMeshRenderer>();if(!mesh||mesh.bones.Length!=67||mesh.sharedMesh.triangles.Length/3!=100000)throw new Exception("Unexpected Island imported geometry/bone inventory");
  string geometry=MeshHash(mesh.sharedMesh);string render=IslandRenderAttributeIdentity.FullMeshHash(mesh.sharedMesh);var clips=AssetDatabase.LoadAllAssetsAtPath(path).OfType<AnimationClip>().Where(c=>!c.name.StartsWith("__preview")).ToArray();
  foreach(string name in Names){var clip=clips.Single(c=>c.name==name);if(clip.humanMotion||Mathf.Abs(clip.length-Durations[Array.IndexOf(Names,name)])>1e-5f)throw new Exception("Raw Generic duration/type gate "+name);Inventory(clip);}
  var controller=AssetDatabase.LoadAssetAtPath<AnimatorController>(Folder+"/original-generic.controller");if(!controller)controller=AnimatorController.CreateAnimatorControllerAtPath(Folder+"/original-generic.controller");var sm=controller.layers[0].stateMachine;foreach(var s in sm.states)sm.RemoveState(s.state);
  for(int i=0;i<Names.Length;i++){
   var clip=clips.Single(c=>c.name==Names[i]);if(clip.humanMotion||Mathf.Abs(clip.length-Durations[i])>1e-5f)throw new Exception("Raw Generic duration/type gate "+clip.name);
   var state=sm.AddState(clip.name);state.motion=clip;state.writeDefaultValues=true;MeasureRaw(model,clip);
  }
  AssetDatabase.SaveAssets();if(Hash(File.ReadAllBytes(templatePath+".meta"))!=templateMetaSHA||Hash(File.ReadAllBytes(templatePath))!=SHA)throw new Exception("Readonly target template changed");if(IslandRenderAttributeIdentity.FullMeshHash(mesh.sharedMesh)!=render||MeshHash(mesh.sharedMesh)!=geometry||Hash(File.ReadAllBytes(input))!=SHA||Hash(File.ReadAllBytes(path))!=SHA)throw new Exception("Source geometry or FBX changed");
  File.WriteAllText("IslandStrikeEvidence/import.txt","sourceSHA="+SHA+"\nmeshSHA="+geometry+"\nvertices="+mesh.sharedMesh.vertexCount+"\ntriangles="+mesh.sharedMesh.triangles.Length/3+"\nbones="+mesh.bones.Length+"\nmaxWeights="+MaxWeights(mesh.sharedMesh)+"\nNo material/image writes. Imported Generic channels; independent Blender trajectory authority gate remains separate and mandatory.\n");
  File.WriteAllText("IslandStrikeEvidence/raw-measurement-complete.json",JsonUtility.ToJson(new RawCompletion{status="RAW_GENERIC_MEASURED_INDEPENDENT_SOURCE_COMPARISON_PENDING",sourceSHA=SHA,rawMetaSHA=Hash(File.ReadAllBytes(path+".meta")),meshSHA=geometry,renderSHA=render,importPolicySHA=Hash(File.ReadAllBytes("IslandStrikeEvidence/import-policy.json")),files=Names.Select(n=>new TakeHash{take=n,sha256=Hash(File.ReadAllBytes("IslandStrikeEvidence/"+n+".trajectory.csv"))}).ToArray()},true));Debug.Log("ISLAND_RAW all3takes inventoried/measured WITHOUT codec. Independent Blender comparison required next.");
 }

 [Serializable]sealed class BindingInfo{public string path,type,propertyName,preWrap,postWrap;public int keys;public float firstTime,lastTime;public bool objectReference;}
 [Serializable]sealed class BindingInventory{public string take,status="INVENTORY_ONLY_NO_CODEC_REQUIREMENT";public float duration;public bool humanMotion;public BindingInfo[] bindings;}
 static void Inventory(AnimationClip clip){var rows=new List<BindingInfo>();foreach(var b in AnimationUtility.GetCurveBindings(clip)){var c=AnimationUtility.GetEditorCurve(clip,b);var keys=c.keys;rows.Add(new BindingInfo{path=b.path,type=b.type.AssemblyQualifiedName,propertyName=b.propertyName,keys=keys.Length,firstTime=keys.Length==0?0:keys[0].time,lastTime=keys.Length==0?0:keys[keys.Length-1].time,preWrap=c.preWrapMode.ToString(),postWrap=c.postWrapMode.ToString()});}foreach(var b in AnimationUtility.GetObjectReferenceCurveBindings(clip)){var keys=AnimationUtility.GetObjectReferenceCurve(clip,b);rows.Add(new BindingInfo{path=b.path,type=b.type.AssemblyQualifiedName,propertyName=b.propertyName,keys=keys.Length,firstTime=keys.Length==0?0:keys[0].time,lastTime=keys.Length==0?0:keys[keys.Length-1].time,objectReference=true});}File.WriteAllText("IslandStrikeEvidence/"+clip.name+".binding-inventory.json",JsonUtility.ToJson(new BindingInventory{take=clip.name,duration=clip.length,humanMotion=clip.humanMotion,bindings=rows.ToArray()},true));}
 static void MeasureRaw(GameObject model,AnimationClip clip){
  var source=UnityEngine.Object.Instantiate(model);foreach(var a in source.GetComponentsInChildren<Animator>())a.enabled=false;var skin=source.GetComponentInChildren<SkinnedMeshRenderer>();var baked=new Mesh();string mesh=MeshHash(skin.sharedMesh),render=IslandRenderAttributeIdentity.FullMeshHash(skin.sharedMesh);
  try{if(skin.bones.Length!=67||skin.bones.Select(b=>b.name).Distinct().Count()!=67)throw new Exception("Raw67bone names not unique");using(var log=new StreamWriter("IslandStrikeEvidence/"+clip.name+".trajectory.csv")){log.WriteLine("seconds,joint,x,y,z,fullSurfaceMinY");int count=Mathf.RoundToInt(Durations[Array.IndexOf(Names,clip.name)]*240);for(int i=0;i<=count;i++){float t=Mathf.Min(i/240f,clip.length);clip.SampleAnimation(source,t);skin.BakeMesh(baked,true);float floor=float.PositiveInfinity;foreach(var v in baked.vertices){var world=skin.transform.TransformPoint(v);if(!Finite(world))throw new Exception("Nonfinite raw original surface");floor=Mathf.Min(floor,world.y);}foreach(var bone in skin.bones){var p=source.transform.InverseTransformPoint(bone.position);if(!Finite(p))throw new Exception("Nonfinite raw bone");log.WriteLine(FormattableString.Invariant($"{t:R},{bone.name},{p.x:R},{p.y:R},{p.z:R},{floor:R}"));}}}if(MeshHash(skin.sharedMesh)!=mesh||IslandRenderAttributeIdentity.FullMeshHash(skin.sharedMesh)!=render)throw new Exception("Raw sampling changed stored mesh/render data");}
  finally{UnityEngine.Object.DestroyImmediate(baked);UnityEngine.Object.DestroyImmediate(source);}
 }
 public static void ExportCodec(){OwnedProject();try{ExportCodecChecked();}catch(Exception e){File.WriteAllText("IslandStrikeEvidence/codec-blocked.json",JsonUtility.ToJson(new CodecFailure{error=e.ToString()},true));throw;}}
 [Serializable]sealed class CodecFailure{public string status="CODEC_BLOCKED_RAW_MEASUREMENTS_RETAINED",error;}
 static void ExportCodecChecked(){
  const string path=Folder+"/Source/model.fbx";var raw=JsonUtility.FromJson<RawCompletion>(File.ReadAllText("IslandStrikeEvidence/raw-measurement-complete.json"));var authority=JsonUtility.FromJson<Authority>(File.ReadAllText("IslandStrikeEvidence/independent-source-trajectory.json"));if(raw.sourceSHA!=SHA||Hash(File.ReadAllBytes(path))!=SHA||Hash(File.ReadAllBytes(path+".meta"))!=raw.rawMetaSHA||Hash(File.ReadAllBytes("IslandStrikeEvidence/import-policy.json"))!=raw.importPolicySHA)throw new Exception("Raw import/input evidence changed after measurement");if(!authority.passed||authority.sourceSHA256!=SHA||authority.fitCount!=1||authority.holdoutPhases!=1800||authority.unityCSVFiles==null||authority.unityCSVFiles.Length!=3)throw new Exception("Independent original Blender trajectory gate must pass BEFORE codec stage");foreach(string n in Names){string actual=Hash(File.ReadAllBytes("IslandStrikeEvidence/"+n+".trajectory.csv"));if(raw.files.Single(f=>f.take==n).sha256!=actual||authority.unityCSVFiles.Single(f=>f.take==n).sha256!=actual)throw new Exception("Authority/raw CSV mismatch "+n);}
  var importer=(ModelImporter)AssetImporter.GetAtPath(path);if(importer.resampleCurves)throw new Exception("No resampling waiver permitted");var model=AssetDatabase.LoadAssetAtPath<GameObject>(path);var mesh=model.GetComponentInChildren<SkinnedMeshRenderer>().sharedMesh;if(MeshHash(mesh)!=raw.meshSHA||IslandRenderAttributeIdentity.FullMeshHash(mesh)!=raw.renderSHA)throw new Exception("Raw imported mesh/render identity changed");var clips=AssetDatabase.LoadAllAssetsAtPath(path).OfType<AnimationClip>().Where(c=>Names.Contains(c.name)).ToArray();
  // Preflight ALL3 before creating any codec assets; unsupported Euler blocks only this stage.
  foreach(string n in Names){var clip=clips.Single(c=>c.name==n);if(clip.humanMotion||AnimationUtility.GetObjectReferenceCurveBindings(clip).Length>0)throw new Exception("Unsupported clip format "+n);foreach(var b in AnimationUtility.GetCurveBindings(clip))if(b.type!=typeof(Transform)||!(b.propertyName.StartsWith("m_LocalPosition.")||b.propertyName.StartsWith("m_LocalRotation.")||b.propertyName.StartsWith("m_LocalScale.")))throw new Exception("Unsupported original binding (NO guessed Euler conversion): "+n+" "+b.path+" "+b.propertyName);}
  var poses=new List<NativeSupportPoseData>();foreach(string n in Names){var clip=clips.Single(c=>c.name==n);var pose=Export(clip,Folder+"/Poses/"+n+".pose.asset");IslandStrikeLosslessPack.PackOnly();poses.Add(pose);Measure(model,clip,pose);}AssetDatabase.SaveAssets();if(MeshHash(mesh)!=raw.meshSHA||IslandRenderAttributeIdentity.FullMeshHash(mesh)!=raw.renderSHA||Hash(File.ReadAllBytes(path))!=SHA||Hash(File.ReadAllBytes(path+".meta"))!=raw.rawMetaSHA)throw new Exception("Codec changed original source/imported render data");
  var controller=AssetDatabase.LoadAssetAtPath<RuntimeAnimatorController>(Folder+"/original-generic.controller");var scene=EditorSceneManager.NewScene(NewSceneSetup.EmptyScene,NewSceneMode.Single);var host=new GameObject("Island native codec EOF review ONLY");var probe=host.AddComponent<IslandStrikeCodecEOFProbe>();probe.model=model;probe.controller=controller;probe.poses=poses.ToArray();EditorSceneManager.SaveScene(scene,Folder+"/codec-eof-review.unity");AssetDatabase.SaveAssets();Debug.Log("ISLAND_CODEC supported original imported channels packed after independent authority gate; native strike quality NOT accepted");
 }

 public static void BuildCodecProbe(){OwnedProject();string output=Arg("-islandReviewPlayer");if(string.IsNullOrEmpty(output))throw new Exception("Supply owned -islandReviewPlayer app path");var result=BuildPipeline.BuildPlayer(new BuildPlayerOptions{scenes=new[]{Folder+"/codec-eof-review.unity"},locationPathName=output,target=BuildTarget.StandaloneOSX,options=BuildOptions.Development});if(result.summary.result!=UnityEditor.Build.Reporting.BuildResult.Succeeded)throw new Exception("Island review player build failed");}
 static int MaxWeights(Mesh m){int max=0;using(var c=m.GetBonesPerVertex())foreach(var n in c)max=Math.Max(max,n);return max;}
 public static string MeshHash(Mesh m){using(var b=new MemoryStream()){using(var w=new BinaryWriter(b,Encoding.UTF8,true)){foreach(var v in m.vertices){w.Write(v.x);w.Write(v.y);w.Write(v.z);}foreach(var v in m.uv){w.Write(v.x);w.Write(v.y);}foreach(int t in m.triangles)w.Write(t);foreach(var a in m.bindposes)for(int i=0;i<16;i++)w.Write(a[i]);using(var c=m.GetBonesPerVertex())foreach(var n in c)w.Write(n);using(var a=m.GetAllBoneWeights())foreach(var n in a){w.Write(n.boneIndex);w.Write(n.weight);}}return Hash(b.ToArray());}}
 static NativeSupportPoseData Export(AnimationClip clip,string path){
  var d=AssetDatabase.LoadAssetAtPath<NativeSupportPoseData>(path);if(!d){d=ScriptableObject.CreateInstance<NativeSupportPoseData>();AssetDatabase.CreateAsset(d,path);}var bs=AnimationUtility.GetCurveBindings(clip);if(bs.Any(b=>b.type!=typeof(Transform)))throw new Exception("Nontransform original binding");var js=new List<NativeSupportPoseData.Joint>();
  using(var memory=new MemoryStream()){using(var w=new BinaryWriter(memory,Encoding.UTF8,true))foreach(string p in bs.Select(b=>b.path).Distinct().OrderBy(p=>p,StringComparer.Ordinal)){var j=new NativeSupportPoseData.Joint{path=p};foreach(var b in bs.Where(b=>b.path==p).OrderBy(b=>b.propertyName,StringComparer.Ordinal)){string f=b.propertyName.StartsWith("m_LocalPosition.")?"p"+b.propertyName.Last():b.propertyName.StartsWith("m_LocalRotation.")?"q"+b.propertyName.Last():b.propertyName.StartsWith("m_LocalScale.")?"s"+b.propertyName.Last():null;if(f==null||!Fields.Contains(f))throw new Exception("Unsupported original curve "+b.propertyName);var c=AnimationUtility.GetEditorCurve(clip,b);typeof(NativeSupportPoseData.Joint).GetField(f).SetValue(j,new AnimationCurve(c.keys){preWrapMode=c.preWrapMode,postWrapMode=c.postWrapMode});w.Write(b.path);w.Write(b.propertyName);w.Write((int)c.preWrapMode);w.Write((int)c.postWrapMode);w.Write(c.length);foreach(var k in c.keys){w.Write(k.time);w.Write(k.value);w.Write(k.inTangent);w.Write(k.outTangent);w.Write(k.inWeight);w.Write(k.outWeight);w.Write((int)k.weightedMode);}}js.Add(j);}d.sourceCurveHash=Hash(memory.ToArray());}
  d.sourceName=clip.name;d.duration=clip.length;d.joints=js.ToArray();EditorUtility.SetDirty(d);return d;
 }
 static void Measure(GameObject model,AnimationClip clip,NativeSupportPoseData pose){
  var source=UnityEngine.Object.Instantiate(model);var replay=UnityEngine.Object.Instantiate(model);var a=source.GetComponent<Animator>();if(a)a.enabled=false;var b=replay.GetComponent<Animator>();if(b)b.enabled=false;var sourceSkin=source.GetComponentInChildren<SkinnedMeshRenderer>();var replaySkin=replay.GetComponentInChildren<SkinnedMeshRenderer>();var baked=new Mesh();var other=new Mesh();var targets=pose.Bind(replay.transform);string before=MeshHash(sourceSkin.sharedMesh);float maxError=0;
  try{using(var log=new StreamWriter("IslandStrikeEvidence/"+clip.name+".codec-trajectory.csv")){log.WriteLine("seconds,joint,x,y,z,fullSurfaceMinY,codecSurfaceMaxError");int count=Mathf.RoundToInt(Durations[Array.IndexOf(Names,clip.name)]*240);for(int i=0;i<=count;i++){float t=Mathf.Min(i/240f,clip.length);clip.SampleAnimation(source,t);pose.Apply(targets,t);sourceSkin.BakeMesh(baked,true);replaySkin.BakeMesh(other,true);var vs=baked.vertices;var rs=other.vertices;if(vs.Length!=rs.Length)throw new Exception("Codec mesh length mismatch");float floor=float.PositiveInfinity,error=0;for(int v=0;v<vs.Length;v++){var x=sourceSkin.transform.TransformPoint(vs[v]);var y=replaySkin.transform.TransformPoint(rs[v]);if(!Finite(x)||!Finite(y))throw new Exception("Nonfinite original/codec surface");floor=Mathf.Min(floor,x.y);error=Mathf.Max(error,Vector3.Distance(x,y));}maxError=Mathf.Max(maxError,error);foreach(var bone in source.GetComponentsInChildren<Transform>()){var p=source.transform.InverseTransformPoint(bone.position);log.WriteLine(FormattableString.Invariant($"{t:R},{bone.name},{p.x:R},{p.y:R},{p.z:R},{floor:R},{error:R}"));}}}if(maxError>0.00001f)throw new Exception("Generic direct-channel/packed fullsurface parity >.01mm: "+maxError);if(MeshHash(sourceSkin.sharedMesh)!=before)throw new Exception("Mesh mutated");File.WriteAllText("IslandStrikeEvidence/"+clip.name+".codec-source-gate.txt","fullSurfaceCodecMaxError="+maxError.ToString("R",System.Globalization.CultureInfo.InvariantCulture)+"\ncurveSHA="+pose.sourceCurveHash+"\n");}
  finally{UnityEngine.Object.DestroyImmediate(baked);UnityEngine.Object.DestroyImmediate(other);UnityEngine.Object.DestroyImmediate(source);UnityEngine.Object.DestroyImmediate(replay);pose.ReleaseDecoded();}
 }
 static bool Finite(Vector3 p)=>float.IsFinite(p.x)&&float.IsFinite(p.y)&&float.IsFinite(p.z);
}
